        return '0,0'
    s = str(n)
    if len(s) <= 3:
        return s + ',' + '0'
    head, tail = s[:-3], s[-3:]
    parts = [head[i:i+2] for i in range(0, len(head)-1, 2)]
    parts.insert(0, head[-2:] if len(head) > 1 else head)
    return ','.join(parts) + ',' + tail

